// Определяем количество сегментов
const int segmentsX = 10; // Количество сегментов по X
const int segmentsY = 10; // Количество сегментов по Y
const int totalSegments = segmentsX * segmentsY;

// Функция для получения случайного индекса
int randomIndex(int seed, int max) {
    return (seed * 48271) % max; // Простой псевдослучайный генератор
}

void mainImage(out vec4 FragColor, in vec2 fragCoord) {
    // Получаем разрешение текстуры
    vec2 resolution = iResolution.xy;

    // Получаем нормализованные координаты фрагмента
    vec2 uv = fragCoord / resolution;

    // Размер каждого сегмента
    vec2 segmentSize = vec2(1.0 / float(segmentsX), 1.0 / float(segmentsY));

    // Определяем текущий сегмент
    int segmentX = int(uv.x / segmentSize.x);
    int segmentY = int(uv.y / segmentSize.y);
    int currentSegmentIndex = segmentX + segmentY * segmentsX;

    // Генерируем случайный индекс на основе времени
    int timeIndex = int(iTime * 10.0); // Увеличиваем скорость перемешивания
    int shuffledIndex = (currentSegmentIndex + randomIndex(timeIndex + currentSegmentIndex, totalSegments)) % totalSegments;

    // Вычисляем координаты перемешанного сегмента
    int shuffledSegmentX = shuffledIndex % segmentsX;
    int shuffledSegmentY = shuffledIndex / segmentsX;

    // Вычисляем UV координаты для перемешанного сегмента
    vec2 shuffledSegmentUV = vec2(float(shuffledSegmentX) * segmentSize.x, float(shuffledSegmentY) * segmentSize.y);

    // Получаем корректные UV координаты для текстуры
    vec2 segmentOffset = vec2(float(segmentX) * segmentSize.x, float(segmentY) * segmentSize.y);
    vec2 textureUV = shuffledSegmentUV + (uv - segmentOffset);

    // Получаем цвет из входного изображения через ichannel0
    vec4 color = texture(iChannel0, textureUV);

    // Устанавливаем цвет фрагмента
    FragColor = color; // Используем выходной параметр FragColor
}
